function D(jv,c){
 var b=jv.base64DecodeToByteArray(String(c)); if(!b||b.length<64)return '';
 var seed='';for(var i=0;i<16;i++)seed+=String.fromCharCode(255&b[i]);
 var key=jv.hexDecodeToByteArray(String(jv.digestHex(seed,'SHA-256')));
 var A=Packages.java.util.Arrays, C=Packages.javax.crypto.Cipher,
     K=Packages.javax.crypto.spec.SecretKeySpec, V=Packages.javax.crypto.spec.IvParameterSpec;
 var ci=C.getInstance('AES/CBC/NoPadding');
 ci.init(C.DECRYPT_MODE,new K(key,'AES'),new V(A.copyOfRange(b,16,32)));
 var p=ci.doFinal(A.copyOfRange(b,32,b.length-16)),r='';
 for(var q=0;q<p.length;q++)r+=String.fromCharCode(255&p[q]);
 while(r.length>0){var cc=r.charCodeAt(r.length-1);if(cc<32||cc===127)r=r.slice(0,-1);else break;}
 return r;
}
function F(s,kind){
 var P={search:['{"list":[{"','{"books":[{"','{"data":{"list":[{"','[{"','{"'],
   details:['{"book_id":1','{"id":1','{"','[{"'],
   source:['{"list":[{"site_id":1','{"data":[{"site_id":1','[{"','{"'],
   city:['{"list":[{"','[{"','{"'],def:['{"list":[{"','[{"','{"','[','','{"data":']}[kind]||['{"','[{"','[',''];
 var S=['','}','}]',']}','"','"}','}"'];
 for(var i=0;i<P.length;i++)for(var j=0;j<S.length;j++){try{return JSON.parse(P[i]+s+S[j])}catch(e){}}
 return null;
}
function P2(jv,t,kind){
 var d=JSON.parse(String(t)).data;
 var c=(d&&typeof d==='object'&&!Array.isArray(d))?d.content:null;
 if(!c)return d;
 var s=D(jv,c);
 return s?(F(s,kind)||s):null;
}
function G(jv,url,kind){return P2(jv,String(jv.ajax(url)),kind)}

// ===== 261109 脱壳 APK 逆向所得：官方正文短密文 = MkAES =====
// 证据链：
//  com.amgcyo.cuttadon.api.repository.CatalogRepository.lambda$getArtChapterContent$4
//    if (is_encrypt) { setName(MkAES.getInstance().decrypt(name)); content=MkAES.getInstance().decrypt(content); }
//  com.amgcyo.cuttadon.api.entity.other.MkCatalog.getName() 同样用 MkAES 解章节名
//  me.jessyan.art.encrypt.MkAES: AES/CBC/PKCS5Padding
//    key = "Pxga!h*e4@T8xfOm" (ASCII 16B)  IV = "E&z!EHGLd$fli*8R" (16B)
//  与旧主协议 D() 是两套完全不同的算法，不可混用。
function MK(jv,c){
 if(!c)return '';
 var b=jv.base64DecodeToByteArray(String(c));
 var key=jv.base64DecodeToByteArray('UHhnYSFoKmU0QFQ4eGZPbQ==');
 var iv=jv.base64DecodeToByteArray('RSZ6IUVIR0xkJGZsaSo4Ug==');
 var C=Packages.javax.crypto.Cipher,
     K=Packages.javax.crypto.spec.SecretKeySpec,
     V=Packages.javax.crypto.spec.IvParameterSpec;
 var ci=C.getInstance('AES/CBC/PKCS5Padding');
 ci.init(C.DECRYPT_MODE,new K(key,'AES'),new V(iv));
 var p=ci.doFinal(b);
 return String(new Packages.java.lang.String(p,'UTF-8'));
}
// 目录章节名：MkAES 解出的真实章节名（失败时按序号兜底）
function MN(jv,n,i){
 if(!n)return '第'+(i+1)+'章';
 try{
  var t=MK(jv,n);
  if(t&&/[\u4e00-\u9fa50-9]/.test(t))return t.replace(/\s+/g,' ').trim();
 }catch(e){}
 return '第'+(i+1)+'章';
}
// 正文清洗：官方 CDN 内嵌了各源站的站尾广告行，逐行剔除（不误伤正常正文）
function MC(jv,t){
 var BAD=/免费阅读|最快.*更新|提供最快|请收藏|记住本站|一秒记住|最新网址|手机阅读|加入书签|请退出转码页面|请下载.*app|下载.*app阅读|章节错误.*举报|本章未完.*下一页|www\.[a-z0-9.-]+\.(com|net|cc|la|info|org|tv)|https?:\/\//i;
 var ls=String(t).replace(/\r\n/g,'\n').replace(/\r/g,'\n').split('\n'),o=[];
 for(var i=0;i<ls.length;i++){
  var L=ls[i];
  if(BAD.test(L))continue;
  if(/^[\s\u3000]*$/.test(L)){if(o.length&&o[o.length-1]!=='')o.push('');continue;}
  o.push(L.replace(/[ \t\u3000]+$/,''));
 }
 return o.join('\n').replace(/\n{3,}/g,'\n\n').trim();
}

// ===== 261109 后半程：ProxyPin 抓包实证的书城域 + 书籍变量选线路 =====
// 书城真实域是 book.yutinglu.com（不是 d.），路径全带 .html 后缀、"全部"筛选用 -1。
// 主协议 D() 返回的是逐字节 latin1 串；source 响应里含中文（site_name/last_chapter_name），
// 必须再反解一次 UTF-8，否则简介里的线路列表是乱码。
function U8(jv,s){
 var by=[];for(var i=0;i<s.length;i++)by.push(s.charCodeAt(i)&255);
 var b64='',ch='ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
 for(var j=0;j<by.length;j+=3){
  var a=by[j],b=j+1<by.length?by[j+1]:0,c=j+2<by.length?by[j+2]:0,n=(a<<16)|(b<<8)|c;
  b64+=ch[(n>>18)&63]+ch[(n>>12)&63]+(j+1<by.length?ch[(n>>6)&63]:'=')+(j+2<by.length?ch[n&63]:'=');
 }
 return String(new Packages.java.lang.String(jv.base64DecodeToByteArray(b64),'UTF-8'));
}
function D8(jv,c){return U8(jv,D(jv,c));}
// 主协议密文 → 解出明文（含中文）→ 补前缀 JSON.parse
// F() 对 source 的前缀候选写死了 {"list":[{"site_id":1（数字），
// 但不少书首条 site_id 是字符串且首块被 IV 覆盖 ⇒ 统一加一层逐对象提取兜底。
function P8(jv,t,kind){
 var d=JSON.parse(String(t)).data;
 var c=(d&&typeof d==='object'&&!Array.isArray(d))?d.content:null;
 if(!c)return d;
 var raw=D8(jv,c);
 var x=F(raw,kind);
 if(x&&typeof x==='object')return x;
 // source 兜底：按 site_path 逐对象括号配平提取（跨书通用，不怕首块被 IV 吃掉）
 var L=OBJS(raw,'"site_path"');
 if(L.length)return {list:L};
 return x||raw;
}
// 通用逐对象提取：按 site_path 锚点定位 → 向前找 '{' → 向后括号配平后 JSON.parse。
// ★261109 晚修复「少一条线路」：主协议 AES/CBC/NoPadding 首块被 IV 覆盖时，
//   第 1 个对象的 "{"site_id":"xxx" 这 16 字节被吃掉，lastIndexOf('{') 返回 -1，
//   原实现静默跳过 ⇒ 5 条只剩 4 条（用户报「我在东京克苏鲁」原APP有5条、阅读只有4条）。
//   修法：首个锚点前无合法 '{' 时，从 raw 开头到本对象第一个 '}' 取残片，
//   剥掉乱码前缀（从第一个合法字段 "crawl_book_id" 起），按 site_path 首段补 site_id，
//   拼成合法 JSON 再 parse。实测补回 biqukan/87.24%/bqk 那条，5/5 齐全。
function OBJS(raw,anchor){
 var out=[],re=/"site_path"\s*:/g,m,anchors=[];re.lastIndex=0;
 while((m=re.exec(raw))!==null)anchors.push(m.index);
 for(var z=0;z<anchors.length;z++){
  var idx=anchors[z],st=raw.lastIndexOf('{',idx);
  if(z>0&&st<anchors[z-1])st=-1;       // 上一个锚点之后的 '{' 才属于本对象
  if(st<0){
   var end=raw.indexOf('}',idx);if(end<0)continue;
   var frag=raw.slice(0,end+1);
   var fm=/"crawl_book_id"\s*:/.exec(frag);
   var body=fm?frag.slice(fm.index):frag;
   body=body.replace(/\s*\}\s*$/,'').replace(/,\s*$/,'');
   var spm=/"site_path"\s*:\s*"([^"]+)"/.exec(body);
   var sid=spm?String(spm[1]).split('/')[0]:'';
   var json='{'+(sid?'"site_id":'+JSON.stringify(sid)+',':'')+body+'}';
   try{var o=JSON.parse(json);if(!o.site_name)o.site_name=sid||o.site_id;
    if(o.site_path)out.push(o)}catch(e){}
   continue;
  }
  var dep=0,q=false,esc=false,e2=-1;
  for(var i=st;i<raw.length;i++){
   var c=raw.charAt(i);
   if(esc){esc=false;continue} if(c==='\\'){esc=true;continue}
   if(c==='"'){q=!q;continue} if(q)continue;
   if(c==='{')dep++; else if(c==='}'){dep--;if(dep===0){e2=i+1;break}}
  }
  if(e2>st){try{var oo=JSON.parse(raw.slice(st,e2));if(oo.site_path)out.push(oo)}catch(e){}}
 }
 return out;
}
// 书城端点：首块被 IV 覆盖导致整体 JSON.parse 必失败，改为从明文里逐对象提取书籍
// （各端点书籍字段一致：author/book_id/form/image/ltype/name/remark/score/status/stype/words_number）
function BOOKS(raw){
 var out=[],re=/"book_id"\s*:\s*(\d+)/g,m;
 while((m=re.exec(raw))!==null){
  var st=raw.lastIndexOf('{',m.index);if(st<0)continue;
  var dep=0,q=false,esc=false,end=-1;
  for(var i=st;i<raw.length;i++){
   var c=raw.charAt(i);
   if(esc){esc=false;continue} if(c==='\\'){esc=true;continue}
   if(c==='"'){q=!q;continue} if(q)continue;
   if(c==='{')dep++; else if(c==='}'){dep--;if(dep===0){end=i+1;break}}
  }
  if(end>st){try{var o=JSON.parse(raw.slice(st,end));if(o&&o.book_id&&o.name)out.push(o)}catch(e){}}
 }
 return out;
}
// 发现页统一的书籍列表：解密 → 捞对象 → 拼 bookUrl（与搜索规则同构）
function EX(jv,result){
 var raw='';
 try{
  var d=JSON.parse(String(result)).data;
  var c=(d&&typeof d==='object'&&!Array.isArray(d))?d.content:null;
  raw=c?D8(jv,c):String(result);
 }catch(e){raw=String(result||'')}
 var L=BOOKS(raw),seen={},o=[];
 for(var i=0;i<L.length;i++){
  var b=L[i],id=String(b.book_id);
  if(seen[id])continue;seen[id]=1;
  o.push(JSON.stringify({
   id:b.book_id,name:b.name,author:b.author,image:b.image,ltype:b.ltype,
   remark:b.remark,words_number:b.words_number,score:b.score,
   bookUrl:'https://d.yutinglu.com/book/details/v4/'+id.slice(0,-3)+'/'+id+'.html'
  }));
 }
 return o;
}
// ★261109 修复「切换路线不生效」：book 绑定只在规则 @js 环境（AnalyzeRule.kt:834），
// jsLib 共享 scope 里没有 book ⇒ 原 CVAR() 恒返回空 ⇒ SEL() 永远默认线路1。
// 与 java 同一定式：jsLib 函数不直接碰宿主绑定，改由规则显式传 bk 进来。
// BaseBook.kt: getCustomVariable() = getVariable("custom")，键名 custom。
function CVAR(bk,jv){
 var vals=[];
 if(bk){
  try{var v=bk.getCustomVariable();if(v!=null&&String(v).length>0)vals.push(String(v))}catch(e){}
  try{var v2=bk.getVariable('custom');if(v2!=null&&String(v2).length>0)vals.push(String(v2))}catch(e2){}
  try{var v3=bk.variable;if(v3!=null&&String(v3).length>0)vals.push(String(v3))}catch(e3){}
 }
 // 兜底：规则环境 java.get(key) 会查 book.getVariable(key)（AnalyzeRule.kt:818-820）
 if(jv){
  try{var g=jv.get('custom');if(g!=null&&String(g).length>0&&String(g)!=='null')vals.push(String(g))}catch(e4){}
  try{var g2=jv.get('lineNo');if(g2!=null&&String(g2).length>0&&String(g2)!=='null')vals.push(String(g2))}catch(e5){}
 }
 for(var i=0;i<vals.length;i++){
  var s=String(vals[i]);
  // 用户可能填纯数字，也可能填 {"custom":"3"} 这类整串；一律抽首个数字
  var m=s.match(/\d+/);
  if(m)return m[0];
 }
 return '';
}
// 选线路：默认按原 App 的 choose 占比取最高；书籍变量若填了数字则强制切到该编号
function SEL(L,bk,jv){
 var best=0,bp=-1;
 for(var i=0;i<L.length;i++){
  var p=parseFloat(String(L[i].choose||'').replace('%',''));if(isNaN(p))p=0;
